package main

import (
	"fmt"
)

func main() {
	var n int
	var t string
	fmt.Scan(&n, &t)

	runes := []rune(t)

	for i := 2; i <= n; i++ {
		if n%i == 0 {
			// Reverse the prefix of length i
			for l, r := 0, i-1; l < r; l, r = l+1, r-1 {
				runes[l], runes[r] = runes[r], runes[l]
			}
		}
	}

	fmt.Println(string(runes))
}

package main

import (
	"fmt"
	"strings"
)

func main() {
	var n int
	var t string
	fmt.Scan(&n, &t)

	for i := 2; i <= n; i++ {
		if n%i == 0 {
			var sb strings.Builder
			sb.Grow(n)
			for j := i - 1; j >= 0; j-- {
				sb.WriteByte(t[j])
			}
			sb.WriteString(t[i:])
			t = sb.String()
		}
	}
	fmt.Println(t)
}

